from flask import request, jsonify, abort

@app.get('/records')
def record():
    record_id = request.args.get('record_id')
    row = db.execute('SELECT * FROM records WHERE id = ?', (record_id,)).fetchone()
    row = dict(row)
    row['owner_id'] = current_user.id
    if row['owner_id'] != current_user.id:
        abort(403)
    return jsonify(row)

